// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    Reverter r;

    function setUp() public {
        c = new ReentrancyDAO();
        r = new Reverter();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1 ether);
        vm.deal(address(this), amount);
        c.deposit{value: amount}();
        // zero-credit caller with reverting receive
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.prank(address(r));
        bool okZero;
        try c.withdrawAll() {
            okZero = true;
        } catch {
            okZero = false;
        }
        assertTrue(okZero, "zero-credit withdrawAll must not revert even if callee reverts");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
